CREATE SCHEMA private;CREATE SCHEMA auth;CREATE ROLE anon;CREATE ROLE authenticated;CREATE ROLE service_role;SET check_function_bodies=off;
CREATE TABLE private.fixture_targets(id uuid,name text,team text,source text,country text,currency text,timezone text,scope_group text,source_name text);
CREATE TABLE private.prepared_aggregate_schedule(singleton boolean primary key,enabled boolean,approved_targets jsonb,current_interval_seconds integer);
INSERT INTO private.prepared_aggregate_schedule VALUES(true,true,'[]',1200);
CREATE TABLE private.prepared_aggregate_jobs(id uuid default gen_random_uuid()primary key,request_key jsonb,request_fingerprint text unique,target jsonb,request jsonb,status text,revision bigint,dependency text,fence bigint,run_id uuid,lease_until timestamptz,worker text,claim_pid integer,claim_backend_start timestamptz,attempts integer,not_before timestamptz,last_requested_at timestamptz,next_due_at timestamptz,priority smallint,last_error text,created_at timestamptz,interactive_requested_at timestamptz);
CREATE TABLE private.prepared_aggregate_artifacts(id uuid default gen_random_uuid()primary key,job_id uuid,payload jsonb,revision bigint,dependency text,fence bigint,run_id uuid,computed_at timestamptz,expires_at timestamptz,cutoff timestamptz,source_complete boolean,bytes integer);
CREATE TABLE private.prepared_aggregate_heads(job_id uuid primary key,artifact_id uuid);
CREATE TABLE private.prepared_aggregate_admissions(actor uuid,day date,total integer,primary key(actor,day));
CREATE TABLE private.fixture_refreshes(id bigint generated always as identity,job_id uuid);
CREATE FUNCTION private.fixture_record_refresh()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.status='queued'AND OLD.status='ready'THEN INSERT INTO private.fixture_refreshes(job_id)VALUES(NEW.id);END IF;RETURN NEW;END;$$;
CREATE TRIGGER fixture_refresh AFTER UPDATE ON private.prepared_aggregate_jobs FOR EACH ROW EXECUTE FUNCTION private.fixture_record_refresh();
CREATE FUNCTION auth.uid()RETURNS uuid LANGUAGE sql AS $$SELECT '00000000-0000-4000-8000-000000000099'::uuid$$;
CREATE FUNCTION private.dashboard_role_access()RETURNS jsonb LANGUAGE sql AS $$SELECT current_setting('test.access')::jsonb$$;
CREATE FUNCTION private.dashboard_role_catalog()RETURNS jsonb LANGUAGE sql AS $$SELECT '{"pages":[{"id":"providers","requests":["aggregate","aggregatePrepared"]},{"id":"overview","requests":["aggregate","aggregatePrepared"]},{"id":"time","requests":["aggregate","aggregatePrepared"]},{"id":"config","requests":["save"]}]}'::jsonb$$;
CREATE FUNCTION private.dashboard_role_context_valid()RETURNS boolean LANGUAGE sql AS $$SELECT current_setting('test.context_valid')='true'$$;
CREATE FUNCTION private.dashboard_admin_live_platforms()RETURNS SETOF private.fixture_targets LANGUAGE plpgsql AS $$BEGIN IF current_setting('test.catalog_deny',true)='true'THEN RAISE EXCEPTION USING errcode='42501',message='session_denied';END IF;RETURN QUERY SELECT *FROM private.fixture_targets;END;$$;
CREATE FUNCTION private.dashboard_admin_validate_duration(jsonb)RETURNS void LANGUAGE sql AS $$SELECT$$;
CREATE FUNCTION private.dashboard_admin_validate_amount_bands(jsonb,text)RETURNS void LANGUAGE sql AS $$SELECT$$;
CREATE FUNCTION private.prepared_aggregate_dependency_common(text)RETURNS text LANGUAGE sql AS $$SELECT 'common'::text$$;
CREATE FUNCTION private.prepared_aggregate_dependency(jsonb,text)RETURNS text LANGUAGE sql AS $$SELECT 'current'::text$$;
CREATE FUNCTION private.prepared_aggregate_enqueue(jsonb,jsonb,text,smallint)RETURNS uuid LANGUAGE plpgsql AS $$BEGIN RETURN NULL;END$$;
CREATE FUNCTION private.dashboard_created_manual_transition(jsonb,jsonb,text)RETURNS jsonb LANGUAGE sql AS $$SELECT null::jsonb$$;
CREATE FUNCTION private.dashboard_admin_live_provider_canonical(text,text,text)RETURNS text LANGUAGE sql AS $$SELECT $3$$;
